const{contextBridge:contextBridge,ipcRenderer:ipcRenderer}=require("electron");contextBridge.exposeInMainWorld("api",{getLayouts:()=>ipcRenderer.invoke("get-keyboard-layouts"),saveLayouts:e=>ipcRenderer.invoke("save-selected-layouts",e),closeSetupWindow:()=>ipcRenderer.send("close-setup-window"),t:e=>t(e)});